#include "llama.h"
#include "ggml-backend.h"
#include <chrono>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

using Clock = std::chrono::steady_clock;
static double seconds(Clock::time_point start) {
    return std::chrono::duration<double>(Clock::now() - start).count();
}
static void require(bool ok, const char * why) {
    if (!ok) throw std::runtime_error(why);
}
static std::string read(const std::filesystem::path & path) {
    std::ifstream file(path, std::ios::binary);
    require(bool(file), "failed to open input");
    return {std::istreambuf_iterator<char>(file), {}};
}
static std::vector<llama_token> tokenize(const llama_vocab * vocab, const std::string & text, bool special) {
    const int n = llama_tokenize(vocab, text.data(), text.size(), nullptr, 0, special, true);
    require(n < 0, "failed to size tokenization");
    std::vector<llama_token> tokens(-n);
    require(llama_tokenize(vocab, text.data(), text.size(), tokens.data(), tokens.size(), special, true) == -n,
            "tokenization length changed");
    return tokens;
}
static void list(const auto & values) {
    std::cout << '[';
    bool first = true;
    for (const auto & value : values) {
        if (!first) std::cout << ',';
        first = false;
        std::cout << value;
    }
    std::cout << ']';
}
static void decode(llama_context * ctx, std::vector<llama_token> & tokens) {
    require(!tokens.empty(), "empty input tokens");
    require(llama_decode(ctx, llama_batch_get_one(tokens.data(), tokens.size())) == 0, "decode failed");
    llama_synchronize(ctx);
}
int main(int argc, char ** argv) try {
    auto start = Clock::now();
    require(argc == 4, "usage: probe MODEL MODE INPUT");
    bool bosun = std::string(argv[2]) == "bosun";
    llama_backend_init();
    ggml_backend_load_all();
    auto gpu = ggml_backend_dev_by_type(GGML_BACKEND_DEVICE_TYPE_GPU);
    require(gpu != nullptr, "Metal device unavailable");
    ggml_backend_dev_t devices[] = {gpu, nullptr};
    auto mp = llama_model_default_params();
    mp.devices = devices;
    mp.n_gpu_layers = 999;
    auto * model = llama_model_load_from_file(argv[1], mp);
    require(model != nullptr, "model load failed");
    const auto * vocab = llama_model_get_vocab(model);
    auto cp = llama_context_default_params();
    cp.n_ctx = bosun ? 2048 : 8192;
    cp.n_batch = bosun ? 2048 : 512;
    cp.n_ubatch = cp.n_batch;
    cp.n_seq_max = 1;
    auto * ctx = llama_init_from_model(model, cp);
    require(ctx != nullptr, "context initialization failed");
    if (bosun) {
        std::string markers;
        for (int i=0; i<256; ++i) {
            char marker[32];
            snprintf(marker, sizeof(marker), "<|decision_%03d|>", i);
            markers += marker;
        }
        auto ids = tokenize(vocab, markers, false);
        require(ids.size() == 256, "decision token count mismatch");
        for (int i=0; i<256; ++i) require(ids[i] == 151669+i, "decision-token mapping mismatch");
    }
    std::cout << "{\"event\":\"ready\",\"seconds\":" << seconds(start) << "}" << std::endl;
    if (bosun) {
        for (int round=0; round<3; ++round) {
            for (int i=0; i<5; ++i) {
                const auto path = std::filesystem::path(argv[3]) / std::to_string(i);
                std::ifstream file(path.string()+".tokens");
                int count;
                require(bool(file >> count) && count >= 2 && count <= 255, "invalid slot count");
                std::vector<llama_token> reference;
                for (llama_token id; file >> id;) reference.push_back(id);
                auto tokens = tokenize(vocab, read(path.string()+".txt"), true);
                require(tokens == reference, "reference token mismatch");
                llama_memory_clear(llama_get_memory(ctx), true);
                auto t = Clock::now();
                decode(ctx, tokens);
                auto * logits = llama_get_logits_ith(ctx, -1);
                require(logits && llama_vocab_n_tokens(vocab) >= 151669+count, "missing slot logits");
                std::vector<float> scores(logits+151669, logits+151669+count);
                for (float s : scores) require(std::isfinite(s), "nonfinite logits");
                const double elapsed = seconds(t);
                std::cout << "{\"event\":\"decision\",\"round\":" << round << ",\"row\":" << i
                          << ",\"tokens\":" << tokens.size() << ",\"seconds\":" << elapsed << ",\"logits\":";
                list(scores);
                std::cout << "}" << std::endl;
            }
        }
    } else {
        auto tokens = tokenize(vocab, read(argv[3]), true);
        std::cout << "{\"event\":\"tokens\",\"ids\":";
        list(tokens);
        std::cout << "}" << std::endl;
        for (int limit : {1,128}) {
            llama_memory_clear(llama_get_memory(ctx), true);
            auto * sampler = llama_sampler_init_greedy();
            auto t = Clock::now();
            decode(ctx, tokens);
            std::vector<llama_token> output;
            auto first = Clock::now();
            while (int(output.size()) < limit) {
                auto token = llama_sampler_sample(sampler, ctx, -1);
                if (llama_vocab_is_eog(vocab, token)) break;
                output.push_back(token);
                if (output.size() == 1) first = Clock::now();
                if (int(output.size()) < limit) {
                    std::vector<llama_token> next{token};
                    decode(ctx, next);
                }
            }
            double elapsed = seconds(t), decode_time = output.empty() ? 0 : seconds(first);
            llama_sampler_free(sampler);
            std::cout << "{\"event\":\"chat\",\"limit\":" << limit << ",\"tokens\":" << output.size()
                      << ",\"prompt_tokens\":" << tokens.size() << ",\"seconds\":" << elapsed
                      << ",\"decode_seconds\":" << decode_time << ",\"output_ids\":";
            list(output);
            std::cout << "}" << std::endl;
        }
    }
    llama_free(ctx);
    llama_model_free(model);
    llama_backend_free();
    return 0;
} catch (const std::exception & e) {
    std::cerr << e.what() << '\n';
    return 1;
}

