use anyhow::{Context, Result, bail, ensure};
use mistralrs::{
    Device, GgufModelBuilder, Model, ModelDType, NormalRequest, Request, RequestMessage, Response,
    SamplingParams, TokenSource,
};
use serde_json::json;
use std::{io::Write, path::Path, time::Instant};

async fn run(model: &Model, tokens: &[u32], id: usize, limit: usize, raw: bool) -> Result<Response> {
    let (tx, mut rx) = tokio::sync::mpsc::channel(1);
    let mut request = NormalRequest::new_simple(
        RequestMessage::CompletionTokens(tokens.to_vec()),
        SamplingParams { max_len: Some(limit), ..SamplingParams::deterministic() },
        tx, id, None, None,
    );
    request.return_raw_logits = raw;
    request.truncate_sequence = false;
    model.inner().get_sender(None)?.send(Request::Normal(Box::new(request))).await?;
    match rx.recv().await.context("empty response")? {
        Response::InternalError(e) | Response::ValidationError(e) => bail!("{e}"),
        Response::CompletionModelError(e, _) | Response::ModelError(e, _) => bail!("{e}"),
        response => Ok(response),
    }
}

async fn tokenize(model: &Model, text: String, special: bool) -> Result<Vec<u32>> {
    Ok(model.tokenize(either::Either::Right(text), None, special, false, None).await?)
}

fn emit(value: serde_json::Value) -> Result<()> {
    println!("{value}");
    std::io::stdout().flush()?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let started = Instant::now();
    let args = std::env::args().skip(1).collect::<Vec<_>>();
    ensure!(args.len() == 3, "usage: probe MODEL MODE INPUT");
    let path = Path::new(&args[0]).canonicalize()?;
    let dir = path.parent().context("missing model directory")?;
    let file = path.file_name().context("missing filename")?.to_string_lossy();
    let bosun = args[1] == "bosun";
    let mut builder = GgufModelBuilder::new(dir.to_string_lossy(), vec![file.as_ref()])
        .with_logging()
        .with_device(Device::new_metal(0)?)
        .with_token_source(TokenSource::None)
        .with_max_model_len(if bosun { 2048 } else { 8192 })
        .with_max_num_seqs(1)
        .with_prefix_cache_n(None);
    if bosun {
        builder = builder
            .with_tokenizer_json(dir.join("bosun-v3.1-0.6b.tokenizer.json").to_string_lossy())
            .with_jinja_explicit(dir.join("bosun-v3.1-0.6b.chat_template.jinja").to_string_lossy().into_owned())
            .with_dtype(ModelDType::F16)
            .with_no_kv_cache();
    }
    let model = builder.build().await?;
    if bosun {
        let markers: String = (0..256).map(|slot| format!("<|decision_{slot:03}|>")).collect();
        ensure!(tokenize(&model, markers, false).await? == (151669..151925).collect::<Vec<_>>(),
                "decision-token mapping mismatch");
    }
    emit(json!({"event":"ready","seconds":started.elapsed().as_secs_f64()}))?;
    if bosun {
        for round in 0..3 {
            for i in 0..5 {
                let root = Path::new(&args[2]);
                let s = std::fs::read_to_string(root.join(format!("{i}.tokens")))?;
                let mut values = s.split_whitespace().map(str::parse::<u32>);
                let count = values.next().context("missing slots")?? as usize;
                let tokens = values.collect::<Result<Vec<_>, _>>()?;
                let text = std::fs::read_to_string(root.join(format!("{i}.txt")))?;
                ensure!(tokenize(&model, text, true).await? == tokens, "reference token mismatch");
                let t = Instant::now();
                let Response::Raw { logits_chunks, tokens: returned } =
                    run(&model, &tokens, round * 5 + i, 1, true).await? else { bail!("expected raw logits"); };
                ensure!(tokens == returned, "engine changed prompt tokens");
                let last = logits_chunks.last().context("missing logits")?;
                let scores = last.narrow(0, last.dim(0)?-1, 1)?.narrow(1,151669,count)?
                    .squeeze(0)?.to_dtype(mistralrs::DType::F32)?.to_vec1::<f32>()?;
                ensure!(scores.iter().all(|v| v.is_finite()), "nonfinite logits");
                emit(json!({"event":"decision","round":round,"row":i,"tokens":tokens.len(),
                            "seconds":t.elapsed().as_secs_f64(),"logits":scores}))?;
            }
        }
    } else {
        let tokens = tokenize(&model, std::fs::read_to_string(&args[2])?, true).await?;
        emit(json!({"event":"tokens","ids":tokens}))?;
        for (i, limit) in [1,128].into_iter().enumerate() {
            let t = Instant::now();
            let Response::CompletionDone(r) = run(&model, &tokens, i, limit, false).await?
                else { bail!("expected completion"); };
            emit(json!({"event":"chat","limit":limit,"tokens":r.usage.completion_tokens,
                        "prompt_tokens":r.usage.prompt_tokens,"seconds":t.elapsed().as_secs_f64(),
                        "decode_seconds":r.usage.total_completion_time_sec,
                        "text":r.choices.first().context("missing completion")?.text}))?;
        }
    }
    Ok(())
}

