#include "llama.h"
#include <iostream>
#include <vector>
int main(int argc, char ** argv) {
    if (argc != 2) return 2;
    auto params = llama_model_default_params();
    params.vocab_only = true;
    params.n_gpu_layers = 0;
    auto * model = llama_model_load_from_file(argv[1], params);
    if (!model) return 3;
    std::vector<llama_token> ids;
    for (llama_token token; std::cin >> token;) ids.push_back(token);
    std::vector<char> output(65536);
    const int n = llama_detokenize(llama_model_get_vocab(model), ids.data(), ids.size(),
                                  output.data(), output.size(), false, true);
    if (n < 0) return 4;
    std::cout.write(output.data(), n);
    llama_model_free(model);
}
